// Authored repairs for the fingerprint-bound second review. Correct option is first;
// the publisher preserves the existing answer identity and display position.
export const repairs=[];
const r=(n,question,options,reasons,clues,steps,cf)=>repairs.push({n,question,options:options.split('|'),reasons:reasons.split('|'),clues:clues.split('|'),steps:steps.split('|'),cf});
